#!/usr/bin/env bash
# Completion check (Stop hook): when the agent says it's done, run the checks.
# Added by Free Rein. Exit 2 sends it back to work with the failures.
input=$(cat)
# already continuing because of this hook: don't loop
printf '%s' "$input" | grep -q '"stop_hook_active": *true' && exit 0
cd "$CLAUDE_PROJECT_DIR" || exit 0
out=$(npm run typecheck 2>&1) || { echo "Not done yet: \`npm run typecheck\` fails:" >&2; echo "$out" | tail -40 >&2; exit 2; }
out=$(npm test 2>&1) || { echo "Not done yet: \`npm test\` fails:" >&2; echo "$out" | tail -40 >&2; exit 2; }
out=$(make lint 2>&1) || { echo "Not done yet: \`make lint\` fails:" >&2; echo "$out" | tail -40 >&2; exit 2; }
out=$(make test 2>&1) || { echo "Not done yet: \`make test\` fails:" >&2; echo "$out" | tail -40 >&2; exit 2; }
exit 0

